<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {useRouter,onBeforeRouteLeave} from 'vue-router'
import {Upload,FolderOpen,FilePlus} from '@lucide/vue'
import {createCloudDataset,listUploadedDatasets,createDatasetUpload,getDatasetUpload,finishDatasetUpload,cancelDatasetUpload,uploadDatasetFile,formatBytes} from '../api/datasetUploads'
import type {UploadedDataset} from '../api/datasetUploads'
import {useDemoStore} from '../stores/demo'
const router=useRouter(),store=useDemoStore(),name=ref(''),format=ref('待识别'),description=ref(''),files=ref<File[]>([]),root=ref('正在连接上传服务…'),maxBytes=ref(0),error=ref(''),busy=ref(false),currentFile=ref(''),sent=ref(0),session=ref<UploadedDataset|null>(null),done=ref(false)
const fileInput=ref<HTMLInputElement>(),folderInput=ref<HTMLInputElement>();let controller:AbortController|undefined
const mode=ref('local'),sourcePath=ref(''),importRoots=ref<string[]>([]);let poll:ReturnType<typeof setTimeout>|undefined
const total=computed(()=>mode.value==='cloud'?(session.value?.total??0):files.value.reduce((n,f)=>n+f.size,0)),progress=computed(()=>done.value?100:total.value?Math.min(99,Math.round(sent.value/total.value*100)):0)
const relative=(f:File)=>f.webkitRelativePath||f.name
async function connect(){try{const data=await listUploadedDatasets();root.value=data.root;importRoots.value=data.importRoots;maxBytes.value=data.maxBytes;error.value=''}catch(e){error.value=e instanceof Error?e.message:'无法连接服务。'}}
onMounted(connect)
function select(event:Event){const input=event.target as HTMLInputElement;files.value=Array.from(input.files??[]);session.value=null;sent.value=0;done.value=false;error.value='';if(files.value.length&&!name.value)name.value=(files.value[0]!.webkitRelativePath.split('/')[0]||files.value[0]!.name).replace(/\.[^.]+$/,'');input.value=''}
async function upload(){if(busy.value)return;if(mode.value==='cloud'){await cloudUpload();return;}error.value='';if(!session.value&&store.datasets.some(d=>d.name===name.value.trim())){error.value='数据集名称已存在，请使用不同名称。';return}if(!files.value.length){error.value='请先选择本机文件或文件夹。';return}if(files.value.length>10000||total.value>maxBytes.value){error.value='文件数量或总大小超过服务端限制。';return}busy.value=true;controller=new AbortController();try{if(!session.value)session.value=await createDatasetUpload({name:name.value,format:format.value,description:description.value,files:files.value.map(f=>({path:relative(f),size:f.size}))});else session.value=await getDatasetUpload(session.value.id);if(session.value.status==='ready'){done.value=true;await store.syncUploadedDatasets();return}let finished=session.value.uploadedBytes;sent.value=finished;for(let i=0;i<files.value.length;i++){if(controller.signal.aborted)throw new Error('上传已暂停，可继续上传。');if(session.value.files[i]?.uploaded)continue;const file=files.value[i]!;currentFile.value=relative(file);await uploadDatasetFile(session.value.id,i,file,bytes=>sent.value=finished+bytes,controller.signal);finished+=file.size;sent.value=finished}if(controller.signal.aborted)throw new Error('上传已暂停，可继续上传。');session.value=await finishDatasetUpload(session.value.id);done.value=true;currentFile.value='';store.notify('数据集文件上传完成。');await store.syncUploadedDatasets().catch(()=>{})}catch(e){error.value=e instanceof Error?e.message:'上传失败。'}finally{busy.value=false}}
async function pollCloud(){
 if(!session.value)return
 try{session.value=await getDatasetUpload(session.value.id);sent.value=session.value.uploadedBytes
 if(session.value.status==='ready'){done.value=true;busy.value=false;await store.syncUploadedDatasets().catch(()=>{});return}
 if(session.value.status!=='copying'){busy.value=false;error.value=session.value.message||'复制已取消。';return}
 error.value=''
 }catch(e){error.value=e instanceof Error?e.message:'无法获取进度，正在重试。'}
 poll=setTimeout(pollCloud,1000)
}
async function cloudUpload(){error.value='';busy.value=true;try{session.value=await createCloudDataset({name:name.value,format:format.value,description:description.value,sourcePath:sourcePath.value});await pollCloud()}catch(e){busy.value=false;error.value=e instanceof Error?e.message:'创建复制任务失败。'}}
async function cancelCloud(){if(!session.value)return;clearTimeout(poll);try{await cancelDatasetUpload(session.value.id);session.value=null;busy.value=false;sent.value=0;error.value=''}catch(e){error.value=e instanceof Error?e.message:'取消失败。';poll=setTimeout(pollCloud,1000)}}
async function discard(){if(!session.value||busy.value)return;busy.value=true;try{await cancelDatasetUpload(session.value.id);session.value=null;sent.value=0;error.value='';store.notify('未完成的上传文件已清理。')}catch(e){error.value=e instanceof Error?e.message:'取消失败。'}finally{busy.value=false}}
function beforeUnload(e:BeforeUnloadEvent){if(busy.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onBeforeUnmount(()=>{clearTimeout(poll);controller?.abort();window.removeEventListener('beforeunload',beforeUnload)})
onBeforeRouteLeave(()=>{if(busy.value){error.value='数据正在传输，请先暂停或取消再离开。';return false}})
</script>
<template><div class="page-heading"><div><div class="eyebrow">ROBOTIC LAB / 数据集</div><h1>新建数据集<span class="heading-dot">.</span></h1><p>从本机上传，或将云容器内已有的数据集复制到平台存储目录。</p></div><button class="button" :disabled="busy" @click="router.push('/datasets')">返回数据集</button></div><div v-if="error" class="form-error" role="alert">{{error}}<button v-if="!maxBytes" type="button" class="text-link" @click="connect">重新连接</button></div><section v-if="done" class="upload-success"><h2>上传完成</h2><p>{{session?.name}} · {{mode==='cloud'?session?.fileCount:files.length}} 个文件 · {{formatBytes(total)}}</p><code>{{session?.path}}</code><p>文件已保存在服务端；Episodes、格式完整性和模型兼容性待解析。</p><button class="button primary" @click="router.push('/datasets')">查看数据集</button></section><form v-else class="dataset-form" @submit.prevent="upload"><div class="form-grid"><label>上传方式<select v-model="mode" :disabled="busy||!!session"><option value="local">本地上传</option><option value="cloud">云端上传</option></select></label><label>数据集名称<input v-model="name" required maxlength="100" :disabled="!!session||busy"/></label><div v-if="mode==='local'" class="file-field"><label>本机数据集文件</label><input ref="fileInput" type="file" multiple hidden @change="select"/><input ref="folderInput" type="file" webkitdirectory multiple hidden @change="select"/><div class="file-buttons"><button type="button" class="button" :disabled="busy||!!session" @click="fileInput?.click()"><FilePlus :size="15"/>选择文件</button><button type="button" class="button" :disabled="busy||!!session" @click="folderInput?.click()"><FolderOpen :size="15"/>选择文件夹</button><span v-if="files.length">{{files.length}} 个文件 · {{formatBytes(total)}}</span></div><p>从打开此网页的电脑选择，不是浏览云服务器目录。文件夹会保留相对路径，压缩包不会自动解压。</p><div v-if="files.length" class="selected-files"><div v-for="(file,i) in files.slice(0,8)" :key="i"><span>{{relative(file)}}</span><small>{{formatBytes(file.size)}}</small></div><p v-if="files.length>8">另有 {{files.length-8}} 个文件</p></div></div><label v-if="mode==='cloud'">云端数据集地址<input v-model="sourcePath" required placeholder="/mnt/data/datasets/pick-bottle" :disabled="busy||!!session"/><small>输入当前云容器内的文件或文件夹绝对路径，复制后保留源数据；不支持 HTTP 或对象存储链接。允许目录：{{importRoots.join('、')||'正在读取…'}}</small></label><label>数据格式<select v-model="format" :disabled="!!session||busy"><option>待识别</option><option>LeRobot</option><option>HDF5</option><option>Parquet</option><option>其他</option></select><small>用于分类标注，不代表已完成格式验证。</small></label><label>场景说明（可选）<textarea v-model="description" rows="3" maxlength="2000" :disabled="!!session||busy"></textarea></label></div><div class="upload-destination"><strong>平台存储目录</strong><code>{{root}}</code><p>服务部署到云容器后，文件上传至云端；当前访问本地开发服务时，文件保存到开发机。单个数据集上限 {{formatBytes(maxBytes)}}，最多 10,000 个文件。</p></div><div v-if="session" class="upload-progress" role="status"><div><strong>{{mode==='cloud'?(busy?'正在扫描 / 复制':session?.status==='failed'?'复制失败':'复制已停止'):(busy?'正在上传':'上传已暂停')}} · {{progress}}%</strong><span>{{formatBytes(sent)}} / {{formatBytes(total)}}</span></div><div class="progress-track"><div :style="{width:progress+'%'}"></div></div><p>{{currentFile}}</p></div><div class="form-actions"><div><button v-if="busy&&mode==='cloud'" type="button" class="button danger" @click="cancelCloud">取消并清理</button><button v-else-if="busy" type="button" class="button" @click="controller?.abort()">暂停上传</button><button v-else-if="session" type="button" class="button danger" @click="discard">取消并清理</button></div><button class="button primary" :disabled="busy||!maxBytes||(mode==='local'?!files.length:!sourcePath.trim()||!!session)"><Upload :size="15"/>{{mode==='cloud'?(busy?'复制中…':'开始复制'):(busy?'上传中…':session?'继续上传':'开始上传')}}</button></div></form></template>
<style scoped>.dataset-form{max-width:900px;border-top:1px solid var(--border);padding-top:24px}.dataset-form .form-grid{grid-template-columns:minmax(0,1fr)}.file-field>label{font-size:12px}.file-buttons{display:flex;align-items:center;gap:10px;margin-top:10px;flex-wrap:wrap}.file-buttons>span{font-size:11px;color:var(--muted)}.file-field p,.upload-destination p{font-size:11px;line-height:1.8;color:var(--muted);margin-top:10px}.selected-files{padding:10px 14px;border:1px solid var(--border);border-radius:7px;margin-top:12px;background:var(--surface)}.selected-files>div{display:flex;justify-content:space-between;gap:15px;padding:7px 0;font-size:11px}.selected-files span{overflow-wrap:anywhere;min-width:0}.selected-files small{color:var(--muted);white-space:nowrap}.upload-destination{border-top:1px solid var(--border);padding-top:20px;margin-top:24px;font-size:12px}.upload-destination strong{font-weight:500;display:block;margin-bottom:8px}.upload-destination code,.upload-success code{font-size:11px;overflow-wrap:anywhere}.upload-progress{margin-top:20px}.upload-progress>div:first-child{display:flex;justify-content:space-between;font-size:11px;margin-bottom:10px}.upload-progress p{font-size:10px;color:var(--muted);margin-top:10px;overflow-wrap:anywhere}.upload-success{padding:30px 0;border-top:1px solid var(--border)}.upload-success h2{font-size:18px;color:#31a180}.upload-success p{font-size:12px;color:var(--muted);margin:18px 0;line-height:1.8}.button:disabled{opacity:.5;cursor:not-allowed}</style>
